<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import type { AuthCredentials } from '../api/auth'
import {
  changeOntologyStatus, compareOntologyReleases, createOntology, createOntologyClass, createOntologyProperty, createOntologyRelation, deleteOntologyClass, deleteOntologyProperty, deleteOntologyRelation,
  listOntologyClasses, listOntologyProperties, listOntologyRelations, listOntologyReleases,
  listOntologies, releaseOntology, type Ontology, type OntologyClass, type OntologyProperty,
  type OntologyRelation, type OntologyRelease, type OntologyPropertyValueType, type OntologyRelationCardinality,
} from '../api/ontology'
import { listProjects, type Project } from '../api/projects'

const props = defineProps<{ credentials: AuthCredentials | null }>()
const projects = ref<Project[]>([])
const ontologies = ref<Ontology[]>([])
const classes = ref<OntologyClass[]>([])
const properties = ref<OntologyProperty[]>([])
const relations = ref<OntologyRelation[]>([])
const releases = ref<OntologyRelease[]>([])
const projectId = ref(''); const ontologyId = ref(''); const classId = ref('')
const ontologyName = ref(''); const className = ref(''); const propertyName = ref(''); const relationName = ref('')
const valueType = ref<OntologyPropertyValueType>('TEXT'); const required = ref(false)
const sourceClassId = ref(''); const targetClassId = ref(''); const cardinality = ref<OntologyRelationCardinality>('ONE_TO_MANY')
const releaseVersion = ref('0.1.0'); const releaseNotes = ref('')
const fromReleaseId = ref(''); const toReleaseId = ref(''); const releaseDiff = ref<{ fromVersion: string; toVersion: string; changes: Array<{ itemId: string; kind: string; changeType: string; name: string; before?: unknown; after?: unknown }> } | null>(null)
const message = ref(''); const error = ref(''); const loading = ref(false)
const selectedOntology = computed(() => ontologies.value.find(item => item.id === ontologyId.value))
const selectedClass = computed(() => classes.value.find(item => item.id === classId.value))
const latestRelease = computed(() => releases.value[0])
const counts = computed(() => ({ classes: classes.value.length, properties: properties.value.length, relations: relations.value.length }))
const diff = computed(() => latestRelease.value ? { classes: counts.value.classes - latestRelease.value.classCount, properties: counts.value.properties - latestRelease.value.propertyCount, relations: counts.value.relations - latestRelease.value.relationCount } : counts.value)
const credentials = () => props.credentials ?? undefined

async function loadProjects() { projects.value = await listProjects(credentials()); if (!projectId.value && projects.value[0]) projectId.value = projects.value[0].id; await loadOntologies() }
async function loadOntologies() { if (!projectId.value) return; ontologies.value = await listOntologies(projectId.value, credentials()); ontologyId.value = ontologies.value[0]?.id ?? ''; await loadModel() }
async function loadModel() {
  if (!projectId.value || !ontologyId.value) { classes.value = []; properties.value = []; relations.value = []; releases.value = []; return }
  classes.value = await listOntologyClasses(projectId.value, ontologyId.value, credentials()); classId.value = classes.value[0]?.id ?? ''
  await Promise.all([loadProperties(), loadRelations(), loadReleases()])
}
async function loadProperties() { properties.value = projectId.value && ontologyId.value && classId.value ? await listOntologyProperties(projectId.value, ontologyId.value, classId.value, credentials()) : [] }
async function loadRelations() { relations.value = projectId.value && ontologyId.value ? await listOntologyRelations(projectId.value, ontologyId.value, credentials()) : [] }
async function loadReleases() { releases.value = projectId.value && ontologyId.value ? await listOntologyReleases(projectId.value, ontologyId.value, credentials()) : []; fromReleaseId.value = releases.value[1]?.id || ''; toReleaseId.value = releases.value[0]?.id || ''; releaseDiff.value = null }
async function run(action: () => Promise<void>) { loading.value = true; error.value = ''; message.value = ''; try { await action() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Request failed' } finally { loading.value = false } }
async function submitOntology() { if (!projectId.value || !ontologyName.value.trim()) return; await run(async () => { const item = await createOntology(projectId.value, ontologyName.value.trim(), '', credentials()); ontologyName.value = ''; await loadOntologies(); ontologyId.value = item.id; await loadModel(); message.value = 'Ontology created' }) }
async function submitClass() { if (!projectId.value || !ontologyId.value || !className.value.trim()) return; await run(async () => { await createOntologyClass(projectId.value, ontologyId.value, className.value.trim(), '', credentials()); className.value = ''; await loadModel(); message.value = 'Class created' }) }
async function submitProperty() { if (!projectId.value || !ontologyId.value || !classId.value || !propertyName.value.trim()) return; await run(async () => { await createOntologyProperty(projectId.value, ontologyId.value, classId.value, { name: propertyName.value.trim(), description: '', valueType: valueType.value, required: required.value }, credentials()); propertyName.value = ''; await loadProperties(); message.value = 'Property added' }) }
async function submitRelation() { if (!projectId.value || !ontologyId.value || !sourceClassId.value || !targetClassId.value || !relationName.value.trim()) return; await run(async () => { await createOntologyRelation(projectId.value, ontologyId.value, { name: relationName.value.trim(), description: '', sourceClassId: sourceClassId.value, targetClassId: targetClassId.value, cardinality: cardinality.value }, credentials()); relationName.value = ''; await loadRelations(); message.value = 'Relation added' }) }
async function removeClass(id: string) { if (!projectId.value || !ontologyId.value) return; await run(async () => { await deleteOntologyClass(projectId.value, ontologyId.value, id, credentials()); await loadModel(); message.value = 'Class deleted' }) }
async function removeProperty(id: string) { if (!projectId.value || !ontologyId.value || !classId.value) return; await run(async () => { await deleteOntologyProperty(projectId.value, ontologyId.value, classId.value, id, credentials()); await loadProperties(); message.value = 'Property deleted' }) }
async function removeRelation(id: string) { if (!projectId.value || !ontologyId.value) return; await run(async () => { await deleteOntologyRelation(projectId.value, ontologyId.value, id, credentials()); await loadRelations(); message.value = 'Relation deleted' }) }
async function publish() { if (!projectId.value || !ontologyId.value || !releaseVersion.value.trim()) return; await run(async () => { await releaseOntology(projectId.value, ontologyId.value, releaseVersion.value.trim(), credentials(), releaseNotes.value.trim()); await loadOntologies(); await loadModel(); message.value = `Ontology released as ${releaseVersion.value}` }) }
async function startDraft() { if (!projectId.value || !ontologyId.value) return; await run(async () => { await changeOntologyStatus(projectId.value, ontologyId.value, 'DRAFT', credentials()); await loadOntologies(); message.value = 'Draft reopened for the next version' }) }
async function compareReleases() { if (!projectId.value || !ontologyId.value || !fromReleaseId.value || !toReleaseId.value || fromReleaseId.value === toReleaseId.value) return; await run(async () => { releaseDiff.value = await compareOntologyReleases(projectId.value, ontologyId.value, fromReleaseId.value, toReleaseId.value, credentials()) }) }
onMounted(() => run(loadProjects))
</script>

<template>
  <section class="workspace" aria-labelledby="ontology-heading">
    <div class="workspace-heading"><div><span class="eyebrow">Ontology studio</span><h2 id="ontology-heading">Model a business context</h2><p>Define classes, properties and relations, then publish a versioned release with a visible change summary.</p></div><span class="api-badge">API v1</span></div>
    <p v-if="error" class="state-message error-message">{{ error }}</p><p v-if="message" class="state-message">{{ message }}</p>
    <div class="ontology-toolbar"><label>Project<select v-model="projectId" @change="loadOntologies"><option v-for="project in projects" :key="project.id" :value="project.id">{{ project.name }}</option></select></label><label>Ontology<select v-model="ontologyId" @change="loadModel"><option v-for="ontology in ontologies" :key="ontology.id" :value="ontology.id">{{ ontology.name }} · {{ ontology.status }}</option></select></label></div>
    <div class="workspace-grid">
      <form class="project-form" @submit.prevent="submitOntology"><span class="section-label">Ontology</span><h3>Create a model</h3><input v-model="ontologyName" required maxlength="120" placeholder="e.g. Customer context" /><button class="primary" :disabled="loading || !projectId || !ontologyName.trim()">Create ontology</button></form>
      <div class="project-list"><div class="list-heading"><div><span class="section-label">Classes</span><h3>{{ classes.length }} class<span v-if="classes.length !== 1">es</span></h3></div><span class="status-badge">{{ selectedOntology?.status || 'EMPTY' }}</span></div><form v-if="selectedOntology?.status === 'DRAFT'" class="inline-form" @submit.prevent="submitClass"><input v-model="className" required maxlength="120" placeholder="Add a class, e.g. Customer" /><button class="primary" :disabled="loading || !className.trim()">Add class</button></form><p v-if="!ontologyId" class="state-message">Create or select an ontology to start modeling.</p><ul v-else class="project-items"><li v-for="item in classes" :key="item.id" class="project-item" :class="{ selected: classId === item.id }"><button type="button" class="item-select" @click="classId = item.id; loadProperties()"><strong>{{ item.name }}</strong><span>{{ item.description || 'Class definition' }}</span></button><span class="item-actions"><span class="status-badge">{{ properties.length && classId === item.id ? `${properties.length} props` : 'CLASS' }}</span><button v-if="selectedOntology?.status === 'DRAFT'" class="delete-button" type="button" @click="removeClass(item.id)">Delete</button></span></li></ul></div>
    </div>
    <div v-if="selectedOntology" class="model-grid">
      <section class="project-list"><div class="list-heading"><div><span class="section-label">Properties</span><h3>{{ selectedClass?.name || 'Select a class' }}</h3></div><span class="api-badge">{{ properties.length }}</span></div><form v-if="selectedOntology.status === 'DRAFT' && selectedClass" class="stack-form" @submit.prevent="submitProperty"><input v-model="propertyName" required maxlength="120" placeholder="Property name, e.g. email" /><div class="form-row"><select v-model="valueType"><option value="TEXT">TEXT</option><option value="NUMBER">NUMBER</option><option value="BOOLEAN">BOOLEAN</option><option value="DATE">DATE</option><option value="REFERENCE">REFERENCE</option></select><label class="check-label"><input v-model="required" type="checkbox" /> required</label><button class="primary" :disabled="loading || !propertyName.trim()">Add</button></div></form><ul class="project-items"><li v-for="item in properties" :key="item.id" class="project-item"><div><strong>{{ item.name }}</strong><span>{{ item.valueType }} · {{ item.required ? 'required' : 'optional' }}</span></div><span class="item-actions"><span class="status-badge">PROP</span><button class="delete-button" type="button" @click="removeProperty(item.id)">Delete</button></span></li></ul><p v-if="selectedClass && !properties.length" class="state-message">No properties defined for this class.</p></section>
      <section class="project-list"><div class="list-heading"><div><span class="section-label">Relations</span><h3>{{ relations.length }} relation<span v-if="relations.length !== 1">s</span></h3></div><span class="api-badge">GRAPH</span></div><form v-if="selectedOntology.status === 'DRAFT' && classes.length > 1" class="stack-form" @submit.prevent="submitRelation"><input v-model="relationName" required maxlength="120" placeholder="Relation name, e.g. owns" /><div class="form-row"><select v-model="sourceClassId"><option value="">From class</option><option v-for="item in classes" :key="`source-${item.id}`" :value="item.id">{{ item.name }}</option></select><select v-model="targetClassId"><option value="">To class</option><option v-for="item in classes" :key="`target-${item.id}`" :value="item.id">{{ item.name }}</option></select></div><div class="form-row"><select v-model="cardinality"><option value="ONE_TO_ONE">ONE_TO_ONE</option><option value="ONE_TO_MANY">ONE_TO_MANY</option><option value="MANY_TO_ONE">MANY_TO_ONE</option><option value="MANY_TO_MANY">MANY_TO_MANY</option></select><button class="primary" :disabled="loading || !relationName.trim() || !sourceClassId || !targetClassId">Add relation</button></div></form><ul class="project-items"><li v-for="item in relations" :key="item.id" class="project-item"><div><strong>{{ item.name }}</strong><span>{{ classes.find(c => c.id === item.sourceClassId)?.name || '?' }} → {{ classes.find(c => c.id === item.targetClassId)?.name || '?' }} · {{ item.cardinality }}</span></div><span class="item-actions"><span class="status-badge">EDGE</span><button class="delete-button" type="button" @click="removeRelation(item.id)">Delete</button></span></li></ul><p v-if="!relations.length" class="state-message">Add two classes to define the first relation.</p></section>
    </div>
    <div v-if="selectedOntology" class="release-grid">
      <section class="project-list"><div class="list-heading"><div><span class="section-label">Release</span><h3>Publish a contract</h3></div><span class="api-badge">{{ counts.classes + counts.properties + counts.relations }} nodes</span></div><form v-if="selectedOntology.status === 'DRAFT'" class="stack-form" @submit.prevent="publish"><div class="form-row"><input v-model="releaseVersion" required pattern="\\d+\\.\\d+\\.\\d+" placeholder="0.1.0" /><button class="primary" :disabled="loading || !releaseVersion.trim()">Publish release</button></div><input v-model="releaseNotes" maxlength="2000" placeholder="Release notes (optional)" /></form><div v-else class="state-message"><p>This ontology is released and read-only.</p><button class="quiet-button" type="button" :disabled="loading" @click="startDraft">Start next draft</button></div><div class="diff-card"><span class="section-label">Current draft changes</span><strong>{{ latestRelease ? 'Current model vs ' + latestRelease.version : 'Unreleased changes' }}</strong><div class="diff-row"><span>Classes</span><b :class="{ positive: diff.classes > 0 }">{{ diff.classes > 0 ? '+' : '' }}{{ diff.classes }}</b><span>Properties</span><b :class="{ positive: diff.properties > 0 }">{{ diff.properties > 0 ? '+' : '' }}{{ diff.properties }}</b><span>Relations</span><b :class="{ positive: diff.relations > 0 }">{{ diff.relations > 0 ? '+' : '' }}{{ diff.relations }}</b></div></div></section>
      <section class="project-list"><div class="list-heading"><div><span class="section-label">History</span><h3>{{ releases.length }} release<span v-if="releases.length !== 1">s</span></h3></div><span class="api-badge">AUDIT</span></div><div v-if="releases.length > 1" class="stack-form"><div class="form-row"><select v-model="fromReleaseId"><option value="">Compare from…</option><option v-for="item in releases" :key="`from-${item.id}`" :value="item.id">{{ item.version }}</option></select><select v-model="toReleaseId"><option value="">Compare to…</option><option v-for="item in releases" :key="`to-${item.id}`" :value="item.id">{{ item.version }}</option></select><button class="primary" type="button" :disabled="loading || !fromReleaseId || !toReleaseId || fromReleaseId === toReleaseId" @click="compareReleases">Compare</button></div></div><div v-if="releaseDiff" class="diff-card"><span class="section-label">Version comparison</span><strong>{{ releaseDiff.fromVersion }} → {{ releaseDiff.toVersion }}</strong><ul class="project-items"><li v-for="(change, index) in releaseDiff.changes" :key="`${change.itemId}-${index}`" class="project-item"><div><strong>{{ change.name }}</strong><span>{{ change.kind }} · {{ change.changeType }}</span></div><span class="status-badge" :data-change="change.changeType">{{ change.changeType }}</span></li></ul><p v-if="!releaseDiff.changes.length" class="state-message">No item-level changes between these releases.</p></div><ul class="project-items"><li v-for="item in releases" :key="item.id" class="project-item"><div><strong>{{ item.version }}</strong><span>{{ item.classCount }} classes · {{ item.propertyCount }} props · {{ item.relationCount }} relations</span></div><span class="status-badge">{{ item.releasedBy || 'system' }}</span></li></ul><p v-if="!releases.length" class="state-message">No releases yet. Publish the draft when the model is ready.</p></section>
    </div>
  </section>
</template>
